import requests
import json

url = "https://partner.shopeemobile.com/api/v2/principal/get_principal_livestream_performance?access_token=access_token&partner_id=partner_id&principal_id=principal_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "end_date": "2026-01-31",
  "granularity": "month",
  "region_list": [
    {
      "currency": "USD",
      "region": "MY"
    }
  ],
  "start_date": "2026-01-01",
  "timezone": "GMT+8"
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

